import { cva, type VariantProps } from 'class-variance-authority';
import type { ComponentProps, ReactNode } from 'react';
import { cn } from '@/lib/cn';

/**
 * # UI primitives
 *
 * Hand-written rather than generated by the shadcn CLI. The CLI's value is
 * putting component source in the repo so it can be read and edited; at the
 * handful of primitives this interface needs — card, button, badge, table,
 * field — writing them directly gets the same property without a 40-file
 * install, and every class here is one somebody chose.
 *
 * Base UI (`@base-ui/react`) is the primitive library where a component needs
 * real behaviour: focus management, dismissal, ARIA wiring. It is used in the
 * expandable rows and the select, not here — these are presentational.
 *
 * **Base UI uses `render` props, not `asChild`.** Noted because the two
 * libraries' docs look alike and `asChild` silently does nothing here.
 */

/* --------------------------------------------------------------------- card */

export function Card({
  className,
  children,
  ...rest
}: ComponentProps<'section'>): React.JSX.Element {
  return (
    <section
      className={cn('border-ink-800 bg-ink-900/60 rounded-lg border backdrop-blur-sm', className)}
      {...rest}
    >
      {children}
    </section>
  );
}

export function CardHeader({
  title,
  hint,
  actions,
}: {
  title: ReactNode;
  hint?: ReactNode;
  actions?: ReactNode;
}): React.JSX.Element {
  return (
    <header className="border-ink-800 flex items-start justify-between gap-4 border-b px-4 py-3">
      <div className="min-w-0">
        <h2 className="text-ink-100 truncate text-sm font-medium">{title}</h2>
        {hint !== undefined && <p className="text-ink-400 mt-0.5 text-xs">{hint}</p>}
      </div>
      {actions !== undefined && <div className="shrink-0">{actions}</div>}
    </header>
  );
}

export function CardBody({ className, children }: ComponentProps<'div'>): React.JSX.Element {
  return <div className={cn('p-4', className)}>{children}</div>;
}

/* ------------------------------------------------------------------- button */

const buttonStyles = cva(
  'inline-flex items-center justify-center gap-2 rounded-md text-sm font-medium transition-colors disabled:cursor-not-allowed disabled:opacity-50',
  {
    variants: {
      variant: {
        primary: 'bg-accent text-ink-950 hover:bg-accent-muted',
        secondary: 'bg-ink-800 text-ink-100 hover:bg-ink-700',
        ghost: 'text-ink-300 hover:bg-ink-800 hover:text-ink-100',
        danger: 'bg-debit/90 text-ink-950 hover:bg-debit',
      },
      size: {
        sm: 'h-7 px-2.5 text-xs',
        md: 'h-9 px-3.5',
      },
    },
    defaultVariants: { variant: 'secondary', size: 'md' },
  },
);

export type ButtonProps = ComponentProps<'button'> & VariantProps<typeof buttonStyles>;

export function Button({ className, variant, size, ...rest }: ButtonProps): React.JSX.Element {
  // `type="button"` by default. The HTML default is `submit`, which makes any
  // button inside a form submit it — a trap that is easy to hit and silent.
  return (
    <button type="button" className={cn(buttonStyles({ variant, size }), className)} {...rest} />
  );
}

/* -------------------------------------------------------------------- badge */

const badgeStyles = cva(
  'inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[11px] font-medium whitespace-nowrap',
  {
    variants: {
      tone: {
        neutral: 'bg-ink-800 text-ink-300',
        credit: 'bg-credit/15 text-credit',
        debit: 'bg-debit/15 text-debit',
        warn: 'bg-warn/15 text-warn',
        accent: 'bg-accent/15 text-accent',
      },
    },
    defaultVariants: { tone: 'neutral' },
  },
);

export type BadgeProps = ComponentProps<'span'> & VariantProps<typeof badgeStyles>;

export function Badge({ className, tone, ...rest }: BadgeProps): React.JSX.Element {
  return <span className={cn(badgeStyles({ tone }), className)} {...rest} />;
}

/* -------------------------------------------------------------------- table */

export function Table({ className, ...rest }: ComponentProps<'table'>): React.JSX.Element {
  return (
    <div className="overflow-x-auto">
      <table className={cn('w-full border-collapse text-sm', className)} {...rest} />
    </div>
  );
}

export function Th({ className, ...rest }: ComponentProps<'th'>): React.JSX.Element {
  return (
    <th
      className={cn(
        'border-ink-800 text-ink-400 border-b px-3 py-2 text-left text-xs font-medium',
        className,
      )}
      {...rest}
    />
  );
}

export function Td({ className, ...rest }: ComponentProps<'td'>): React.JSX.Element {
  return <td className={cn('border-ink-800/60 border-b px-3 py-2', className)} {...rest} />;
}

/**
 * A numeric cell: monospaced, tabular figures, right-aligned.
 *
 * Right-aligned and tabular so a column of amounts lines up at the decimal
 * point, which is the one thing a column of money has to do. Proportional
 * digits make `1,111.11` and `9,999.99` different widths and the column
 * unreadable.
 */
export function TdNum({ className, ...rest }: ComponentProps<'td'>): React.JSX.Element {
  return <Td className={cn('num text-right whitespace-nowrap', className)} {...rest} />;
}

export function ThNum({ className, ...rest }: ComponentProps<'th'>): React.JSX.Element {
  return <Th className={cn('text-right', className)} {...rest} />;
}

/* -------------------------------------------------------------- empty/error */

export function Empty({ children }: { children: ReactNode }): React.JSX.Element {
  return <p className="text-ink-400 px-3 py-8 text-center text-sm">{children}</p>;
}

export function ErrorNote({ children }: { children: ReactNode }): React.JSX.Element {
  return (
    <p className="border-debit/40 bg-debit/10 text-debit rounded border px-3 py-2 text-sm">
      {children}
    </p>
  );
}

/**
 * A skeleton row, sized to the table it sits in.
 *
 * Deliberately not a spinner. A spinner says "something is happening"; a
 * skeleton says "a table of this shape is about to appear", and the page does
 * not reflow when it does.
 */
export function SkeletonRows({ columns, rows = 5 }: { columns: number; rows?: number }) {
  return (
    <>
      {Array.from({ length: rows }, (_, row) => (
        <tr key={row}>
          {Array.from({ length: columns }, (_, column) => (
            <Td key={column}>
              <span className="bg-ink-800 block h-3 animate-pulse rounded" />
            </Td>
          ))}
        </tr>
      ))}
    </>
  );
}

/* -------------------------------------------------------------------- field */

export function Field({
  label,
  hint,
  error,
  children,
}: {
  label: string;
  hint?: string;
  error?: string;
  children: ReactNode;
}): React.JSX.Element {
  return (
    <label className="block">
      <span className="text-ink-300 mb-1 block text-xs font-medium">{label}</span>
      {children}
      {error !== undefined ? (
        <span className="text-debit mt-1 block text-xs">{error}</span>
      ) : (
        hint !== undefined && <span className="text-ink-500 mt-1 block text-xs">{hint}</span>
      )}
    </label>
  );
}

export function Input({ className, ...rest }: ComponentProps<'input'>): React.JSX.Element {
  return (
    <input
      className={cn(
        'border-ink-700 bg-ink-950 text-ink-100 placeholder:text-ink-600 num h-9 w-full rounded-md border px-3 text-sm',
        className,
      )}
      {...rest}
    />
  );
}

export function Select({ className, ...rest }: ComponentProps<'select'>): React.JSX.Element {
  /*
   * A native `<select>`, not a Base UI Select.
   *
   * Base UI's Select is the right choice when the trigger needs custom content
   * or the options need rich rendering. These are short lists of plain strings,
   * where the native control is keyboard-accessible, screen-reader-correct and
   * mobile-native for free — and a custom one would be strictly worse at all
   * three for no gain.
   */
  return (
    <select
      className={cn(
        'border-ink-700 bg-ink-950 text-ink-100 h-9 w-full rounded-md border px-2 text-sm',
        className,
      )}
      {...rest}
    />
  );
}
